static bool parse_ra_string(const char *s, float *out)
{
    if (s == NULL || *s == '\0') {
        return false;
    }

    if (strchr(s, ':')) {
        int h = 0;
        int m = 0;
        float sec = 0.0f;
        if (sscanf(s, "%d:%d:%f", &h, &m, &sec) != 3) {
            return false;
        }

        float value = (float)h + (float)m / 60.0f + sec / 3600.0f;
        if (!valid_ra(value)) {
            return false;
        }

        *out = value;
        return true;
    }

    char *end = NULL;
    float value = strtof(s, &end);
    if (end == s) {
        return false;
    }

    if (!valid_ra(value)) {
        return false;
    }

    *out = value;
    return true;
}

