static bool qr_solve_full(const double *A, const double *b, int n, double *x)
{
    double r[OS_CALIBRATION_MAX_STARS][3];
    double y[OS_CALIBRATION_MAX_STARS];
    double v[OS_CALIBRATION_MAX_STARS];

    for (int i = 0; i < n; i++) {
        r[i][0] = A[i * 3 + 0];
        r[i][1] = A[i * 3 + 1];
        r[i][2] = A[i * 3 + 2];
        y[i] = b[i];
    }

    for (int k = 0; k < 3; k++) {
        double norm = 0.0;
        for (int i = k; i < n; i++) {
            norm += r[i][k] * r[i][k];
        }
        norm = sqrt(norm);

        if (norm < 1e-12) {
            return false;
        }

        memset(v, 0, sizeof(v));
        for (int i = k; i < n; i++) {
            v[i] = r[i][k];
        }

        if (v[k] >= 0.0) {
            v[k] += norm;
        } else {
            v[k] -= norm;
        }

        double unorm = 0.0;
        for (int i = k; i < n; i++) {
            unorm += v[i] * v[i];
        }
        unorm = sqrt(unorm);

        if (unorm < 1e-12) {
            return false;
        }

        for (int i = k; i < n; i++) {
            v[i] /= unorm;
        }

        for (int col = k; col < 3; col++) {
            double dot = 0.0;
            for (int i = k; i < n; i++) {
                dot += v[i] * r[i][col];
            }

            for (int i = k; i < n; i++) {
                r[i][col] -= 2.0 * v[i] * dot;
            }
        }

        double dot_y = 0.0;
        for (int i = k; i < n; i++) {
            dot_y += v[i] * y[i];
        }

        for (int i = k; i < n; i++) {
            y[i] -= 2.0 * v[i] * dot_y;
        }
    }

    double m[3][3];
    for (int i = 0; i < 3; i++) {
        m[i][0] = r[i][0];
        m[i][1] = r[i][1];
        m[i][2] = r[i][2];
    }

    double b3[3] = { y[0], y[1], y[2] };

    if (fabs(m[2][2]) < 1e-12) {
        return false;
    }

    x[2] = b3[2] / m[2][2];

    if (fabs(m[1][1]) < 1e-12) {
        return false;
    }

    x[1] = (b3[1] - m[1][2] * x[2]) / m[1][1];

    if (fabs(m[0][0]) < 1e-12) {
        return false;
    }

    x[0] = (b3[0] - m[0][1] * x[1] - m[0][2] * x[2]) / m[0][0];

    return true;
}

double A[OS_CALIBRATION_MAX_STARS * 3];
double b_ra[OS_CALIBRATION_MAX_STARS];
double b_dec[OS_CALIBRATION_MAX_STARS];

for (uint8_t i = 0; i < s_align_star_count; i++) {
