static bool align_check_collinearity_3star(void)
{
    double x[3];
    double y[3];

    for (int i = 0; i < 3; i++) {
        x[i] = (double)s_align_stars[i].ra_hours * 15.0 * 3600.0;
        y[i] = (double)s_align_stars[i].dec_degrees * 3600.0;
    }

    double det = x[0] * (y[1] - y[2]) -
                 y[0] * (x[1] - x[2]) +
                 (x[1] * y[2] - y[1] * x[2]);

    return fabs(det) < 1e-6;
}

