    if (!s_rtc_initialized) {
        return OS_ERR_NOT_SUPPORTED;
    }

    *utc_epoch_seconds = s_rtc_epoch;
    return OS_ERR_NONE;
}

os_error_t os_hal_rtc_set(uint32_t utc_epoch_seconds)
{
    s_rtc_epoch = utc_epoch_seconds;
    s_rtc_initialized = true;
    return OS_ERR_NONE;
}

